in case someone is interested:
```python

import aclib
from archicad import ACConnection
aclib.port = 19723

connection = ACConnection(aclib.port)


ARCHICAD_IFC_ID_GUID = "84A027A9-F2F1-40B4-A900-70A422B10829"


def get_selected_elements():
    try:
        selectedElements = aclib.RunTapirCommand(
            'GetSelectedElements', {})["elements"]
    except Exception as e:
        print(f"Error occurred while fetching selected elements: {e}")
        return []
    if not selectedElements:
        return []
    return selectedElements


def get_property_values_official(elements, property_ids):
    try:
        values = connection.commands.GetPropertyValuesOfElements(
            elements=elements, properties=property_ids)
    except:
        return []
    return values


def get_property_values_tapir(elements, property_ids):
    try:
        values = aclib.RunTapirCommand("GetPropertyValuesOfElements", {
            "elements": elements,
            "properties": property_ids
        })["propertyValuesForElements"]
    except:
        return []
    return values


if __name__ == "__main__":
    elements = get_selected_elements()
    values = get_property_values_official(elements, [{"propertyId": {
        "guid": ARCHICAD_IFC_ID_GUID}}])
    print(f"Official response : {values}")
    values = get_property_values_tapir(elements, [{"propertyId": {
        "guid": ARCHICAD_IFC_ID_GUID}}])
    print(f"Tapir response : {values}")
```

